    const f = airForm || {};
    const t = (v) => String(v || '').trim();
    const options = (Array.isArray(f.airports) ? f.airports : [])
      .map(x => (t(x.name) || t(x.code))
        ? { name: t(x.name) || null, code: t(x.code) ? t(x.code).toUpperCase() : null, note: t(x.note) || null }
        : null)
      .filter(Boolean);
